using Greyhaven.Content;
using Greyhaven.Server;
using System.Text.Json;
using var p=new ContentPackage(Path.GetFullPath(args[0]),Path.Combine(Path.GetFullPath(args[0]),"content/original/maps/reach-fixture.json"));var world=new OriginalWorld(p);var baseline=Wire.Encode(world.State);int count=0;
void Assert(bool condition,string why="Assertion failed"){if(!condition)throw new Exception(why);}
EnemyState Enemy()=>world.State.Combat.Enemies.First();
void Tick(double seconds){for(int n=0;n<(int)Math.Round(seconds*10);n++)world.Advance(.1);}
void Good(Command c){var r=world.Handle(c);Assert(r.Ok,r.Message);}
void Bad(Command c){string before=Wire.Encode(world.State);var r=world.Handle(c);Assert(!r.Ok,"Unexpected success");Assert(before==Wire.Encode(world.State),"Rejected action mutated the world");}
void Cast(string name,string target="",int x=21,int y=19)=>Good(new(){Type="cast",ItemId="greyhaven.spell."+name,TargetId=target,X=x,Y=y});
void Test(string name,Action test){world.Restore(new(){Map=p.Map,MapHash=p.MapHash,Fingerprint=p.Fingerprint,State=JsonSerializer.Deserialize<SessionState>(baseline,ContentPackage.Json)!});var s=world.State;s.Paused=false;s.X=20;s.Y=19;s.Z=p.Map.Get(20,19).Z;foreach(var e in s.Combat.Enemies.Skip(1)){e.Health=0;e.Behavior="Dead";}Enemy().X=21;Enemy().Y=19;Enemy().Z=p.Map.Get(21,19).Z;Enemy().AttackAt=1000;Enemy().MoveAt=0;test();CombatRules.Validate(p,world.State);InventoryRules.Validate(p,world.State);count++;Console.WriteLine("PASS "+name);}
Test("five distinct original enemy archetypes and eight active spells initialize",()=>{Assert(world.State.Combat.Enemies.Count==5);Assert(CombatRules.Enemies.Select(e=>e.Actor).Distinct().Count()==5);Assert(p.Definitions.Spells.All(s=>s.RulesEnabled)&&CombatRules.Spells.Length==8);});
Test("melee commits damage and enforces swing timing",()=>{int hp=Enemy().Health;Good(new(){Type="attack",TargetId=Enemy().Id});Assert(Enemy().Health==hp-12);Good(new(){Type="attack",TargetId=Enemy().Id});Assert(Enemy().Health==hp-12);Tick(1.1);Assert(Enemy().Health<hp-12);});
Test("enemy defeat spawns loot exactly once and stays defeated",()=>{Good(new(){Type="attack",TargetId=Enemy().Id});Tick(2.5);Assert(Enemy().Health==0&&world.State.Combat.Kills==1&&Enemy().LootSpawned);int loot=world.State.Items.Count(i=>i.Id=="loot."+Enemy().Id);Assert(loot==1);Tick(3);Assert(world.State.Items.Count(i=>i.Id=="loot."+Enemy().Id)==1);Bad(new(){Type="attack",TargetId=Enemy().Id});});
Test("throw consumes one carried crystal and resolves a real projectile",()=>{int amount=world.State.Items.First(i=>i.Definition.EndsWith("tide-crystal")).Amount;Good(new(){Type="throw",TargetId=Enemy().Id});Assert(world.State.Items.First(i=>i.Definition.EndsWith("tide-crystal")).Amount==amount-1);Assert(Enemy().Health==32);Tick(.6);Assert(Enemy().Health==18);Bad(new(){Type="throw",TargetId=Enemy().Id});});
Test("ranged invalid targets and insufficient ammo are atomic",()=>{Enemy().X=28;Enemy().Y=19;Bad(new(){Type="throw",TargetId=Enemy().Id});Enemy().X=21;world.State.Items.RemoveAll(i=>i.Definition.EndsWith("tide-crystal"));world.State.Quickbar=world.State.Quickbar.Select(b=>b.StartsWith("item:")&&InventoryRules.Find(world.State,b[5..])==null?"":b).ToList();Bad(new(){Type="throw",TargetId=Enemy().Id});});
Test("Dawn spends mana and cleanses poison while restoring health",()=>{world.State.Combat.Health=50;world.State.Combat.Status.PoisonUntil=20;world.State.Combat.Status.NextPulse=1;Cast("dawn");Assert(world.State.Combat.Mana==54&&world.State.Combat.Health==50);Tick(.5);Assert(world.State.Combat.Health==68&&world.State.Combat.Status.PoisonUntil==0);});
Test("Renew heals over time rather than immediately",()=>{world.State.Combat.Health=40;Cast("renew");Tick(.9);Assert(world.State.Combat.Health==40);Tick(3.3);Assert(world.State.Combat.Health>=48&&world.State.Combat.Health<=60);});
Test("Ward reduces incoming damage",()=>{Cast("ward");Tick(.6);Enemy().AttackAt=0;Tick(.1);Assert(world.State.Combat.Health==98,"Shield and ward must reduce a 6-damage hit to 2");});
Test("Ember delivers impact and persistent burn",()=>{Enemy().Health=32;Cast("ember",Enemy().Id);Tick(1.1);Assert(Enemy().Health==14&&Enemy().Status.BurnUntil>world.State.ElapsedSeconds);Tick(1.2);Assert(Enemy().Health<14);});
Test("Venom delivers poison pulses",()=>{Cast("venom",Enemy().Id);Tick(1.1);Assert(Enemy().Health==26&&Enemy().Status.PoisonUntil>world.State.ElapsedSeconds);Tick(1.2);Assert(Enemy().Health<26);});
Test("Bind stops enemy movement while status is active",()=>{Enemy().X=23;Cast("bind",Enemy().Id);Tick(.6);int x=Enemy().X,y=Enemy().Y;Tick(1);Assert(Enemy().X==x&&Enemy().Y==y&&Enemy().Status.RootUntil>world.State.ElapsedSeconds);});
Test("Storm damages several visible enemies and applies slow",()=>{var second=world.State.Combat.Enemies[1];second.Health=50;second.X=22;second.Y=19;second.Z=0;second.AttackAt=1000;Cast("storm",x:21,y:19);Tick(1.1);Assert(Enemy().Health==16);Assert(world.State.Combat.Enemies[1].Health<50&&Enemy().Status.SlowUntil>world.State.ElapsedSeconds);});
Test("Gate moves only to a visible unoccupied valid tile",()=>{Cast("gate",x:20,y:21);Tick(1);Assert(world.State.X==20&&world.State.Y==21);});
Test("Gate rejects occupied, off-map and obstructed destinations",()=>{Bad(new(){Type="cast",ItemId="greyhaven.spell.gate",X=21,Y=19});Bad(new(){Type="cast",ItemId="greyhaven.spell.gate",X=int.MaxValue,Y=19});string old=p.Map.Get(20,20).Terrain;try{p.Map.Get(20,20).Terrain="greyhaven.terrain.water";Bad(new(){Type="cast",ItemId="greyhaven.spell.gate",X=20,Y=21});}finally{p.Map.Get(20,20).Terrain=old;}});
Test("casting validates mana, target type and range before spending",()=>{world.State.Combat.Mana=0;Bad(new(){Type="cast",ItemId="greyhaven.spell.ember",TargetId=Enemy().Id});world.State.Combat.Mana=60;Bad(new(){Type="cast",ItemId="greyhaven.spell.bind",X=21,Y=19});Bad(new(){Type="cast",ItemId="unknown"});});
Test("accepted movement interrupts a cast without refund",()=>{Cast("ember",Enemy().Id);Good(new(){Type="step",Dx=0,Dy=1});Assert(world.State.Combat.Cast==null&&world.State.Combat.Mana==52);});
Test("damage interrupts casting",()=>{Enemy().AttackAt=0;Cast("storm",x:21,y:19);Tick(.1);Assert(world.State.Combat.Cast==null&&world.State.Combat.Health<100);});
Test("manual cancellation retains paid mana and recovery",()=>{Cast("ember",Enemy().Id);Good(new(){Type="cancel-cast"});Assert(world.State.Combat.Cast==null&&world.State.Combat.Mana==52);Bad(new(){Type="cast",ItemId="greyhaven.spell.dawn"});});
Test("pause freezes projectiles, AI, regen and cast timers",()=>{Cast("ember",Enemy().Id);world.State.Paused=true;string before=Wire.Encode(world.State);Tick(2);Assert(Wire.Encode(world.State)==before);Bad(new(){Type="attack",TargetId=Enemy().Id});});
Test("tonics consume one unit and enforce recovery",()=>{world.State.Combat.Health=40;int n=world.State.Items.First(i=>i.Definition.EndsWith("healing-tonic")).Amount;Good(new(){Type="drink"});Assert(world.State.Combat.Health==70&&world.State.Items.First(i=>i.Definition.EndsWith("healing-tonic")).Amount==n-1);Bad(new(){Type="drink"});});
Test("last consumed tonic clears its quickbar identity",()=>{var tonic=world.State.Items.First(i=>i.Definition.EndsWith("healing-tonic"));tonic.Amount=1;world.State.Quickbar[0]="item:"+tonic.Id;world.State.Combat.Health=50;Good(new(){Type="drink",ItemId=tonic.Id});Assert(InventoryRules.Find(world.State,tonic.Id)==null&&world.State.Quickbar[0]=="");});
Test("safe camp prevents outgoing attacks and enemy aggression",()=>{world.State.X=p.Map.Spawn.X;world.State.Y=p.Map.Spawn.Y;Bad(new(){Type="attack",TargetId=Enemy().Id});int hp=world.State.Combat.Health;Enemy().AttackAt=0;Tick(2);Assert(world.State.Combat.Health==hp&&Enemy().Behavior is "Return" or "Idle");});
Test("enemy pursuit uses integer tiles and does not overlap player",()=>{Enemy().X=24;Tick(1.8);Assert(Enemy().X<24&&CombatRules.Distance(Enemy().X,Enemy().Y,world.State.X,world.State.Y)>=1);});
Test("ranged enemies retreat at close range",()=>{Enemy().Kind="slinger";Enemy().Health=36;Tick(.1);Assert(CombatRules.Distance(Enemy().X,Enemy().Y,world.State.X,world.State.Y)>1);});
Test("hexer root prevents player movement",()=>{Enemy().Kind="hexer";Enemy().Health=42;Enemy().X=24;Enemy().AttackAt=0;Tick(.1);Assert(world.State.Combat.Status.RootUntil>0);Bad(new(){Type="step",Dx=0,Dy=1});});
Test("leashed enemies return instead of pursuing indefinitely",()=>{Enemy().HomeX=7;Enemy().HomeY=20;Tick(.1);Assert(Enemy().Behavior is "Return" or "Idle");});
Test("player cannot walk into a living enemy",()=>Bad(new(){Type="step",Dx=1,Dy=0}));
Test("death creates an anchored pack and blocks ghost inventory actions",()=>{world.State.Combat.Health=1;Enemy().AttackAt=0;Tick(.1);Assert(world.State.Combat.Dead&&world.State.Combat.Health==0&&world.State.Combat.CorpseId!="");var pack=InventoryRules.Find(world.State,world.State.Combat.CorpseId)!;Assert(pack.Where=="ground"&&world.State.Items.All(i=>i.Where is not ("bag" or "equipped")));Bad(new(){Type="transfer",ItemId=pack.Id,Destination="bag"});Bad(new(){Type="step",Dx=0,Dy=1});});
Test("recovery and reclaim preserve every carried item identity",()=>{var carried=world.State.Items.Where(i=>InventoryRules.Carried(world.State,i)).Select(i=>i.Id).ToHashSet();world.State.Combat.Health=1;Enemy().AttackAt=0;Tick(.1);int x=world.State.X,y=world.State.Y;Good(new(){Type="recover"});Assert(world.State.X==p.Map.Spawn.X&&world.State.Combat.GraceUntil>world.State.ElapsedSeconds);world.State.X=x;world.State.Y=y;world.State.Z=p.Map.Get(x,y).Z;Good(new(){Type="reclaim"});Assert(world.State.Combat.CorpseId==""&&carried.SetEquals(world.State.Items.Where(i=>InventoryRules.Carried(world.State,i)).Select(i=>i.Id)));});
Test("save reload retains pending casts, mana, enemy health and statuses",()=>{Cast("ember",Enemy().Id);Enemy().Status.RootUntil=8;string temp=Path.Combine(Path.GetTempPath(),"greyhaven-combat-"+Guid.NewGuid());try{var store=new CampaignStore(temp,"slot1");store.Write(p,world.State,"manual");string expected=Wire.Encode(world.State);world.Restore(store.Read("manual"));world.State.Paused=false;Assert(Wire.Encode(world.State)==expected);Tick(1.2);Assert(Enemy().Health<32);}finally{Directory.Delete(temp,true);}});
Test("combat save validator rejects unknown enemies and invalid timers",()=>{var s=JsonSerializer.Deserialize<SessionState>(baseline,ContentPackage.Json)!;s.Combat.Enemies[0].Kind="unknown";try{CombatRules.Validate(p,s);throw new Exception("Expected validation failure");}catch(ContentException){}s=JsonSerializer.Deserialize<SessionState>(baseline,ContentPackage.Json)!;s.Combat.SwingAt=double.NaN;try{CombatRules.Validate(p,s);throw new Exception("Expected timer failure");}catch(ContentException){}});
Test("in-flight projectile survives reload and applies damage only once",()=>{Good(new(){Type="throw",TargetId=Enemy().Id});var save=new CampaignSave{Map=p.Map,MapHash=p.MapHash,Fingerprint=p.Fingerprint,State=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!};world.Restore(save);world.State.Paused=false;Tick(.6);int health=Enemy().Health;Assert(health==18);Tick(.6);Assert(Enemy().Health==health);});
Test("moved-out-of-range spell target fizzles without a mana refund",()=>{Cast("ember",Enemy().Id);Enemy().X=27;Enemy().Y=17;Enemy().Z=p.Map.Get(27,17).Z;Enemy().MoveAt=1000;Tick(.8);Assert(Enemy().Health==32&&world.State.Combat.Mana==52&&world.State.Combat.Cast==null);});
Test("occupied Gate destination at resolution cannot overlap actors",()=>{Cast("gate",x:20,y:21);Enemy().X=20;Enemy().Y=21;Enemy().MoveAt=1000;Tick(1);Assert(world.State.X==20&&world.State.Y==19);});
Test("deepest legal nested bag survives corpse wrapping and reclaim",()=>{string parent=world.State.Items.First(i=>i.Definition.EndsWith("field-satchel")).Id;for(int n=0;n<8;n++){string id="nested."+n;world.State.Items.Add(new(){Id=id,Definition="greyhaven.item.field-satchel",Where="container",ParentId=parent,X=70,Y=150});parent=id;}InventoryRules.Validate(p,world.State);world.State.Combat.Health=1;Enemy().AttackAt=0;Tick(.1);InventoryRules.Validate(p,world.State);int x=world.State.X,y=world.State.Y;Good(new(){Type="recover"});world.State.X=x;world.State.Y=y;world.State.Z=p.Map.Get(x,y).Z;Good(new(){Type="reclaim"});Assert(world.State.Items.Any(i=>i.Id=="nested.7"));});
Test("full item pool death conserves all items without adding an invalid corpse",()=>{for(int n=world.State.Items.Count;n<InventoryRules.MaxItems;n++)world.State.Items.Add(new(){Id="pool."+n,Definition=InventoryRules.Currency,Where="ground",Amount=1,X=20,Y=20});var ids=world.State.Items.Select(i=>i.Id).ToHashSet();world.State.Combat.Health=1;Enemy().AttackAt=0;Tick(.1);Assert(world.State.Combat.Dead&&world.State.Combat.CorpseId==""&&ids.SetEquals(world.State.Items.Select(i=>i.Id)));});
Test("explicit ranged shortcut consumes its own stack identity",()=>{var original=world.State.Items.First(i=>i.Definition.EndsWith("tide-crystal"));world.State.Items.Add(new(){Id="second.crystal",Definition=original.Definition,Amount=2,X=80,Y=150});Good(new(){Type="throw",TargetId=Enemy().Id,ItemId="second.crystal"});Assert(InventoryRules.Find(world.State,original.Id)!.Amount==3&&InventoryRules.Find(world.State,"second.crystal")!.Amount==1);});
Test("dead saves retain corpse contents and recover exactly once",()=>{world.State.Combat.Health=1;Enemy().AttackAt=0;Tick(.1);string corpse=world.State.Combat.CorpseId;var ids=world.State.Items.Select(i=>i.Id).ToHashSet();var save=new CampaignSave{Map=p.Map,MapHash=p.MapHash,Fingerprint=p.Fingerprint,State=JsonSerializer.Deserialize<SessionState>(Wire.Encode(world.State),ContentPackage.Json)!};world.Restore(save);Assert(world.State.Combat.Dead&&world.State.Combat.CorpseId==corpse&&ids.SetEquals(world.State.Items.Select(i=>i.Id)));world.State.Paused=false;Good(new(){Type="recover"});Bad(new(){Type="recover"});Assert(world.State.Items.Count(i=>i.Id==corpse)==1);});
Console.WriteLine(count+" combat, magic and AI checks passed.");
